import{_ as t,H as o,f as n,i as r}from"./chunks/framework.DLd0CbzH.js";const m=JSON.parse('{"title":"Hormones 101 — Estrogen, Testosterone & Anti-Androgens","description":"A foundational guide to how estrogen, testosterone, anti-androgens, and progesterone work in trans feminine hormone therapy.","frontmatter":{"title":"Hormones 101 — Estrogen, Testosterone & Anti-Androgens","description":"A foundational guide to how estrogen, testosterone, anti-androgens, and progesterone work in trans feminine hormone therapy."},"headers":[],"relativePath":"trans-female/intro/hormones-101.md","filePath":"trans-female/intro/hormones-101.md"}'),s={name:"trans-female/intro/hormones-101.md"};function a(i,e,l,d,h,g){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="hormones-101-estrogen-testosterone-anti-androgens" tabindex="-1">Hormones 101: Estrogen, Testosterone &amp; Anti-Androgens <a class="header-anchor" href="#hormones-101-estrogen-testosterone-anti-androgens" aria-label="Permalink to &quot;Hormones 101: Estrogen, Testosterone &amp; Anti-Androgens&quot;">​</a></h1><h2 id="what-are-hormones" tabindex="-1">What Are Hormones? <a class="header-anchor" href="#what-are-hormones" aria-label="Permalink to &quot;What Are Hormones?&quot;">​</a></h2><p>Hormones are chemical messengers in your body. They travel through your bloodstream and tell cells what to do — like &quot;grow breast tissue&quot; or &quot;produce sperm&quot;.</p><p>For trans feminine HRT, we focus on four main players:</p><ol><li><strong>Estrogen</strong> — the primary feminising hormone</li><li><strong>Testosterone</strong> — the primary masculinising hormone we want to reduce</li><li><strong>Anti-androgens</strong> — blockers that reduce testosterone&#39;s effects</li><li><strong>Progesterone</strong> — an optional further feminising hormone</li></ol><h2 id="estrogen" tabindex="-1">Estrogen <a class="header-anchor" href="#estrogen" aria-label="Permalink to &quot;Estrogen&quot;">​</a></h2><p>Estrogen is the primary female sex hormone. It is responsible for:</p><ul><li>Breast development</li><li>Fat distribution to hips, thighs, and face</li><li>Skin softening</li><li>Slowing body and facial hair growth</li><li>Regulating menstrual cycles in cisgender women</li></ul><p>In trans women, we take <strong>estradiol</strong> — the main biologically active form of endogenous estrogen — to bring levels into a cisgender female range.</p><h3 id="the-estradiol-molecule" tabindex="-1">The Estradiol Molecule <a class="header-anchor" href="#the-estradiol-molecule" aria-label="Permalink to &quot;The Estradiol Molecule&quot;">​</a></h3><p>Estradiol&#39;s chemical formula is <strong>C₁₈H₂₄O₂</strong> (molar mass: 272.38 g/mol). Like all steroid hormones, it is built on a four-ring backbone: three six-membered cyclohexane rings (A, B, C) fused to one five-membered cyclopentane ring (D) — the cyclopentanoperhydrophenanthrene skeleton. Key features:</p><ul><li>Ring A is <strong>aromatic</strong> (benzene-like), shown with a dashed circle</li><li><strong>–OH at C3</strong> on ring A (a phenol group, due to the aromatic ring)</li><li><strong>–OH at C17β</strong> on ring D</li><li><strong>–CH₃ at C13</strong> (carbon-18), the C/D ring junction</li></ul><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/a/ac/Estradiol_3D_ball.png/1280px-Estradiol_3D_ball.png" alt="Estrogen ball molecule" width="500" height="600"><h3 id="how-estrogen-works" tabindex="-1">How Estrogen Works <a class="header-anchor" href="#how-estrogen-works" aria-label="Permalink to &quot;How Estrogen Works&quot;">​</a></h3><p>Estradiol enters cells and binds to <strong>estrogen receptors</strong> (ERα and ERβ), activating genes that drive feminine physical development. It also:</p><ul><li><strong>Lowers LH and FSH</strong> — reducing testosterone production in the testes via negative feedback on the HPG axis</li><li><strong>Increases SHBG</strong> (sex hormone-binding globulin) — which binds to remaining free testosterone, making it hormonally inactive</li><li><strong>Promotes breast duct growth</strong> — the first step in breast development</li></ul><h2 id="testosterone" tabindex="-1">Testosterone <a class="header-anchor" href="#testosterone" aria-label="Permalink to &quot;Testosterone&quot;">​</a></h2><p>Testosterone is the primary male sex hormone. In trans women, we want to lower its levels or block its effects, because it:</p><ul><li>Stimulates facial and body hair growth</li><li>Deepens the voice (a permanent change; HRT cannot reverse it)</li><li>Increases muscle mass and bone density</li><li>Promotes male pattern hair loss</li></ul><h3 id="the-testosterone-molecule" tabindex="-1">The Testosterone Molecule <a class="header-anchor" href="#the-testosterone-molecule" aria-label="Permalink to &quot;The Testosterone Molecule&quot;">​</a></h3><p>Testosterone&#39;s chemical formula is <strong>C₁₉H₂₈O₂</strong> (molar mass: 288.42 g/mol). It shares the same four-ring steroid backbone as estradiol — three six-membered rings and one five-membered ring — but differs in key functional groups: it has a ketone (=O) at position 3 on ring A instead of a hydroxyl group, and an extra methyl carbon giving it 19 carbons vs estradiol&#39;s 18.</p><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/3/3f/Testosterone_molecule_ball.png/1280px-Testosterone_molecule_ball.png" alt="Testosterone ball molecule" width="500" height="600"><h3 id="the-aromatase-connection" tabindex="-1">The Aromatase Connection <a class="header-anchor" href="#the-aromatase-connection" aria-label="Permalink to &quot;The Aromatase Connection&quot;">​</a></h3><p>Your body contains an enzyme called <strong>aromatase</strong> that can convert testosterone into estradiol. This is why:</p><ul><li>Some people assigned male at birth naturally have measurable estradiol levels</li><li>Even at low testosterone levels, some conversion to estradiol may occur in trans women</li></ul><p>The goal of HRT is not just to convert T into E, but to actively suppress T production and block its effects — hence why anti-androgens are used alongside estradiol.</p><h2 id="anti-androgens-testosterone-blockers" tabindex="-1">Anti-Androgens (Testosterone Blockers) <a class="header-anchor" href="#anti-androgens-testosterone-blockers" aria-label="Permalink to &quot;Anti-Androgens (Testosterone Blockers)&quot;">​</a></h2><p>Anti-androgens stop testosterone from working. There are two main approaches:</p><table tabindex="0"><thead><tr><th>Type</th><th>How it works</th><th>Examples</th></tr></thead><tbody><tr><td><strong>Receptor blockers</strong></td><td>Bind to androgen receptors, preventing T from activating them</td><td>Bicalutamide, Spironolactone (partial)</td></tr><tr><td><strong>Production suppressors</strong></td><td>Reduce the testes&#39; testosterone output via the HPG axis</td><td>Cyproterone acetate, GnRH agonists</td></tr></tbody></table><h3 id="the-hpg-axis" tabindex="-1">The HPG Axis <a class="header-anchor" href="#the-hpg-axis" aria-label="Permalink to &quot;The HPG Axis&quot;">​</a></h3><p>To understand how anti-androgens and estrogen suppress testosterone, you need to know the <strong>hypothalamus–pituitary–gonadal (HPG) axis</strong>:</p><ol><li>The <strong>hypothalamus</strong> releases GnRH (gonadotropin-releasing hormone)</li><li>The <strong>pituitary gland</strong> responds by releasing LH and FSH</li><li>The <strong>testes</strong> produce testosterone in response to LH</li></ol><p>Estrogen disrupts this loop via negative feedback — high estradiol signals the hypothalamus and pituitary to reduce LH and FSH output, which in turn lowers testosterone production. GnRH agonists work differently: they flood the GnRH receptors continuously, causing them to desensitise and stop responding, which eventually shuts down LH/FSH and testosterone production almost entirely.</p><div class="info custom-block"><p class="custom-block-title">Why use both estrogen and an anti-androgen?</p><p>Estrogen alone can suppress testosterone, but often not reliably to female range — particularly with oral pills. Combining estrogen with an anti-androgen provides more consistent suppression and allows lower estrogen doses, reducing some risks. Most prescribing guidelines recommend using both until testosterone is stably suppressed, at which point some people transition to estrogen monotherapy (typically via injections or high-dose transdermal).</p></div><h2 id="progesterone" tabindex="-1">Progesterone <a class="header-anchor" href="#progesterone" aria-label="Permalink to &quot;Progesterone&quot;">​</a></h2><p>Progesterone is another naturally occurring female hormone. It is not strictly necessary for trans feminine HRT, but some trans women choose to add it for:</p><ul><li><strong>Breast maturation</strong> — possible help with Tanner stage 4/5 development (evidence is largely anecdotal; robust clinical trials are lacking)</li><li><strong>Libido</strong> — may increase sexual desire in some individuals</li><li><strong>Mood and sleep</strong> — some report a calming effect; others experience the opposite</li></ul><p>The recommended form is <strong>micronised progesterone</strong> (Utrogestan/Prometrium) taken orally or rectally at 100–200 mg/day. Synthetic progestins (e.g. medroxyprogesterone acetate) are generally not recommended as they have a less favourable side effect profile.</p><div class="warning custom-block"><p class="custom-block-title">Progesterone side effects</p><p>Progesterone can cause mood swings, depression, fatigue, or weight gain in some individuals. If adding it, start at a lower dose and monitor how you respond before increasing.</p></div><div class="tip custom-block"><p class="custom-block-title">When to add progesterone</p><p>Most clinicians who prescribe progesterone recommend waiting until at least 6–12 months into estrogen therapy, to allow baseline breast development to establish first.</p></div><h2 id="hormone-level-targets" tabindex="-1">Hormone Level Targets <a class="header-anchor" href="#hormone-level-targets" aria-label="Permalink to &quot;Hormone Level Targets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Hormone</th><th>Target Range</th><th>Purpose</th></tr></thead><tbody><tr><td>Estradiol (E2)</td><td>100–200 pg/mL</td><td>Feminisation, bone health, T suppression</td></tr><tr><td>Testosterone (T)</td><td>&lt; 50 ng/dL</td><td>Suppress masculine traits</td></tr><tr><td>Progesterone</td><td>Not routinely measured</td><td>Dose guided by symptoms and response</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">These are guidelines, not hard rules</p><p>Not everyone will achieve both E2 and T targets simultaneously — see the &quot;Key Hormone Targets &amp; Monitoring&quot; section of the main guide for more detail on this.</p></div><h2 id="how-estrogen-and-anti-androgens-work-together" tabindex="-1">How Estrogen and Anti-Androgens Work Together <a class="header-anchor" href="#how-estrogen-and-anti-androgens-work-together" aria-label="Permalink to &quot;How Estrogen and Anti-Androgens Work Together&quot;">​</a></h2><p>The two mechanisms complement each other and can be thought of in two streams:</p><p><strong>Estrogen&#39;s indirect T suppression (via HPG axis):</strong> Exogenous estradiol → raises blood E2 → hypothalamus and pituitary detect high E2 → LH and FSH output drops → testes receive less LH signal → testosterone production falls</p><p><strong>Anti-androgen action (receptor blockade or direct suppression):</strong> Bicalutamide/spironolactone → competes with T at androgen receptors → T cannot activate target cells, even if still present CPA/GnRH agonists → suppress LH/FSH directly → testes produce less T upstream</p><p>Using both is generally more effective and reliable than either alone, particularly earlier in transition before hormone levels are fully stable.</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Hormone</th><th>Role in Trans Feminine HRT</th><th>How We Modify It</th></tr></thead><tbody><tr><td><strong>Estradiol</strong></td><td>Primary feminising hormone</td><td>Added via pills, patches, gel, or injections</td></tr><tr><td><strong>Testosterone</strong></td><td>Masculinising hormone to suppress</td><td>Reduced with estrogen + anti-androgens</td></tr><tr><td><strong>Progesterone</strong></td><td>Optional; possible breast maturation and mood benefits</td><td>Added after 6–12 months as micronised progesterone</td></tr><tr><td><strong>SHBG</strong></td><td>Binds and inactivates free sex hormones</td><td>Rises naturally with estradiol; not directly targeted</td></tr><tr><td><strong>LH / FSH</strong></td><td>Signals testes to produce T</td><td>Suppressed by estradiol and CPA/GnRH agonists</td></tr></tbody></table>',50)])])}const p=t(s,[["render",a]]);export{m as __pageData,p as default};
